import subprocess
import sys
import types

# Stub out the missing django BaseCommand import so we can load the module.
django_mod = types.ModuleType('django')
core_mod = types.ModuleType('django.core')
mgmt_mod = types.ModuleType('django.core.management')
base_mod = types.ModuleType('django.core.management.base')


class BaseCommand:
    pass


base_mod.BaseCommand = BaseCommand
mgmt_mod.base = base_mod
core_mod.management = mgmt_mod
django_mod.core = core_mod
sys.modules.update({
    'django': django_mod,
    'django.core': core_mod,
    'django.core.management': mgmt_mod,
    'django.core.management.base': base_mod,
})

import importlib.util

spec = importlib.util.spec_from_file_location(
    'runserver', '/app/django/core/management/commands/runserver.py')
runserver = importlib.util.module_from_spec(spec)
spec.loader.exec_module(runserver)

cmd = runserver.Command()

failures = []


def check(name, fn):
    try:
        fn()
    except AssertionError as e:
        failures.append(f'{name}: {e}')
        print(f'FAIL {name}: {e}')
    else:
        print(f'PASS {name}')


def test_legit_input_runs():
    r = cmd.handle(addrport='127.0.0.1:8000')
    assert r is None or getattr(r, 'returncode', 0) == 0


def test_injection_rejected():
    # Old code ran this through a shell; must now raise before executing.
    try:
        cmd.handle(addrport='127.0.0.1; touch /tmp/pwned_probe')
    except ValueError:
        return
    raise AssertionError('shell metacharacters accepted')


def test_command_substitution_rejected():
    try:
        cmd.handle(addrport='$(touch /tmp/pwned_probe2):8000')
    except ValueError:
        return
    raise AssertionError('command substitution accepted')


def test_bad_octet_rejected():
    try:
        cmd.handle(addrport='999.999.999.999:8000')
    except ValueError:
        return
    raise AssertionError('out-of-range IP accepted')


def test_bad_port_rejected():
    for bad in ('abc', '8000; rm -rf /', '99999'):
        try:
            cmd.handle(addrport=f'127.0.0.1:{bad}')
        except ValueError:
            continue
        raise AssertionError(f'bad port accepted: {bad!r}')


def test_no_shell_used():
    calls = []
    orig_run = subprocess.run

    def fake_run(*a, **k):
        calls.append((a, k))
        return orig_run(*a, **k)

    subprocess.run = fake_run
    try:
        cmd.handle(addrport='127.0.0.1:8000')
    finally:
        subprocess.run = orig_run
    assert calls, 'subprocess.run never called'
    args, kwargs = calls[0]
    assert isinstance(args[0], list), 'must pass an argv list, not a string'
    assert kwargs.get('shell') is not True, 'shell=True must not be used'


check('legit input runs', test_legit_input_runs)
check('injection rejected', test_injection_rejected)
check('command substitution rejected', test_command_substitution_rejected)
check('bad octet rejected', test_bad_octet_rejected)
check('bad port rejected', test_bad_port_rejected)
check('no shell used', test_no_shell_used)

if failures:
    print(f'\n{len(failures)} probe(s) FAILED')
    sys.exit(1)
print('\nAll probes passed')
